const body = $input.first().json.body || $input.first().json;
let raw = String(body.sender || body.phone || body.from || '').trim();
let digits = raw.replace(/[^0-9]/g, '');
if (digits.startsWith('0')) {
  digits = '62' + digits.slice(1);
}
if (!digits.startsWith('62')) {
  digits = '62' + digits;
}
return [{
  json: {
    ...body,
    phone_normalized: digits,
    message_text: body.message || body.text || ''
  }
}];

const row = $input.first().json;
const now = DateTime.now().setZone('Asia/Jakarta');
let inHours = false;

if (row.Mode === 'Selalu') {
  inHours = true;
} else if (row.Mode === 'Jam Harian') {
  const [openH, openM] = String(row['Jam Buka']).split(':').map(Number);
  const [closeH, closeM] = String(row['Jam Tutup']).split(':').map(Number);
  const openDt = now.set({ hour: openH, minute: openM, second: 0 });
  const closeDt = now.set({ hour: closeH, minute: closeM, second: 0 });
  inHours = now >= openDt && now <= closeDt;
} else if (row.Mode === 'Rentang Tanggal') {
  const start = DateTime.fromFormat(row['Mulai (tanggal+jam)'], 'yyyy-MM-dd HH:mm', { zone: 'Asia/Jakarta' });
  const end = DateTime.fromFormat(row['Selesai (tanggal+jam)'], 'yyyy-MM-dd HH:mm', { zone: 'Asia/Jakarta' });
  inHours = now >= start && now <= end;
}

return [{ json: { ...($('NormalizePhoneNumber').first().json), in_hours: inHours } }];

