const out = $json;
const phone = $('NormalizePhoneNumber').first().json.phone_normalized;
const detail = out.order_detail || {};
const items = detail.items || [];
const total = detail.total || 0;
const nama = detail.nama || '';
const metodeKirim = detail.metode_kirim || '';
const metodeBayar = detail.metode_bayar || '';
const alamatPengiriman = detail.alamat_pengiriman || '';
const jumlah = items.reduce((a, i) => a + (i.qty || 1), 0);
const validPhone = /^62[0-9]{8,13}$/.test(phone);

const menuCache = ($('GetCachedMenu').first().json.menu) || [];
let stockIssue = null;
for (const item of items) {
  const menuRow = menuCache.find(m => m.Menu === item.menu);
  const stok = menuRow ? Number(menuRow['Stok Tersisa']) : null;
  if (stok !== null && !isNaN(stok) && (item.qty || 1) > stok) {
    stockIssue = `Maaf kak, stok ${item.menu} tinggal ${stok}, sedangkan diminta ${item.qty}. Mau dikurangi jumlahnya atau ganti menu?`;
    break;
  }
}

const basicValid = validPhone && items.length > 0 && total > 0 && !!nama && !!metodeKirim && !!metodeBayar;
const isValid = basicValid && !stockIssue;
const statusPembayaran = metodeBayar === 'QRIS' ? 'Menunggu Verifikasi' : 'Bayar di Tempat';
const validationMessage = stockIssue || 'Maaf, sepertinya ada data order yang belum lengkap. Boleh diulang lagi menu dan jumlahnya? 🙏';

return [{ json: {
  ...out,
  phone_normalized: phone,
  is_valid: isValid,
  jumlah,
  items_json: JSON.stringify(items),
  nama,
  metode_kirim: metodeKirim,
  metode_bayar: metodeBayar,
  alamat_pengiriman: alamatPengiriman,
  status_pembayaran: statusPembayaran,
  validation_message: validationMessage
} }];

