let parsed = null;
let parseFailed = false;
let rawText = $json.output || $json.text || '';
try {
  let raw = String(rawText).trim();
  raw = raw.replace(/^```json/i, '').replace(/^```/, '').replace(/```$/, '').trim();
  parsed = JSON.parse(raw);
} catch (e) {
  parseFailed = true;
}
if (parseFailed || !parsed || typeof parsed !== 'object') {
  return [{ json: { parse_failed: true, raw_output: rawText } }];
}
return [{ json: { ...parsed, parse_failed: false } }];

const items = ($json.order_detail && $json.order_detail.items) || [];
const menuCache = ($('GetCachedMenu').first().json.menu) || [];
return items.map(item => {
  const menuRow = menuCache.find(m => m.Menu === item.menu);
  const oldStok = menuRow ? Number(menuRow['Stok Tersisa']) : null;
  const newStok = (oldStok !== null && !isNaN(oldStok)) ? Math.max(oldStok - (item.qty || 1), 0) : null;
  return { json: { Menu: item.menu, newStok } };
}).filter(i => i.json.newStok !== null);

